import { MeshStandardNodeMaterial, PlaneGeometry, Mesh } from 'three/webgpu';
import { color, vec3, mix, smoothstep, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Vector2, Raycaster, Vector3 } = ctx.THREE;
  const group = new Group();

  const colors = config.intent?.visualSpec?.colors ?? {
    background: "#0b0b10",
    surface: "#101015",
    ink: "#16161d",
    paper: "#e8ecf2",
    accent: "#ff2a38",
    gradientStops: [{ at: 0, hex: "#121218" }, { at: 1, hex: "#0b0b10" }]
  };

  const cStop0 = colors.gradientStops?.[0]?.hex ?? "#121218";
  const cStop1 = colors.gradientStops?.[1]?.hex ?? "#0b0b10";
  const cPaper = colors.paper ?? "#e8ecf2";
  const cAccent = colors.accent ?? "#ff2a38";

  // --- STAGE / FOOTER BAND BACKGROUND ---
  // Width: 6.8 units, Height: 2.0 units
  const bgGeo = new PlaneGeometry(6.8, 2.0, 1, 1);
  const bgMat = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.2,
    transparent: true,
    opacity: 1
  });

  // Vertical gradient in fragment shader
  const gradNode = mix(
    color(cStop0),
    color(cStop1),
    smoothstep(0.0, 1.0, uv().y)
  );
  bgMat.colorNode = gradNode;

  const bgMesh = new Mesh(bgGeo, bgMat);
  bgMesh.receiveShadow = true;
  group.add(bgMesh);

  // --- HAIRLINES & ACCENT BAR ---
  // Top hairline: Y = 1.0 - 0.003 = 0.997, color: #23232b
  const topHairlineMat = new MeshStandardNodeMaterial({
    color: 0x23232b,
    roughness: 0.5,
    metalness: 0.8
  });
  const topHairline = new Mesh(new PlaneGeometry(6.8, 0.006), topHairlineMat);
  topHairline.position.set(0, 0.997, 0.001);
  group.add(topHairline);

  // Bottom hairline (above legal line): Y = -0.625, separating text and legal line
  const bottomHairlineMat = new MeshStandardNodeMaterial({
    color: 0x23232b,
    roughness: 0.5,
    metalness: 0.8
  });
  const bottomHairline = new Mesh(new PlaneGeometry(6.8, 0.006), bottomHairlineMat);
  bottomHairline.position.set(0, -0.45, 0.001);
  group.add(bottomHairline);

  // Accent bar beneath Wordmark: left 2.0 units zone (Y ~ 0.25)
  const accentBarMat = new MeshStandardNodeMaterial({
    color: cAccent,
    emissive: cAccent,
    emissiveIntensity: 1.4,
    roughness: 0.2
  });
  const accentBar = new Mesh(new PlaneGeometry(0.3, 0.02), accentBarMat);
  // Center left bounds: band x ranges [-3.4, 3.4]. Left 2.0 zone is roughly x ∈ [-3.4, -1.4]
  accentBar.position.set(-2.4, 0.25, 0.002);
  group.add(accentBar);

  // --- TEXT INTERACTIVE / LAYOUT ---
  const activeItems = [];
  const cleanupTasks = [];

  const addText = (content, size, colorHex, x, y, align = 'left') => {
    // Standardize scene units using a sensible mapping for 1000px scale font atlas
    // e.g., 34px -> ~0.34 units, 13px -> ~0.13 units, 9px -> ~0.09 units
    const textMesh = ctx.fontAtlas.createText(content, {
      fontSize: size * 10, // Font scale normalization
      color: colorHex,
      align: align
    });
    textMesh.position.set(x, y, 0.005);
    // Explicit bounding setup for custom raycasting interactions
    const s = size * 0.01;
    textMesh.scale.set(s, s, s);
    group.add(textMesh);
    return textMesh;
  };

  // 1. Wordmark (Left 2.0 units)
  addText("NOVA ATELIER", 34, cPaper, -3.2, 0.35, 'left');

  // Columns definition: Col 1 starts at x = -0.8, gutters 0.375, width 1.2
  const colX = [-0.8, 0.775, 2.35];

  // Col 1: ATELIER
  addText("ATELIER", 9, "#7f838a", colX[0], 0.65, 'left');
  const linksCol1 = [
    { text: "Features", route: "hub-features" },
    { text: "Collection", route: "hub-collection" },
    { text: "Pricing", route: "hub-pricing" }
  ];
  linksCol1.forEach((link, idx) => {
    const mesh = addText(link.text, 13, cPaper, colX[0], 0.4 - (idx * 0.2), 'left');
    mesh.userData = { link: link.route, originalColor: cPaper };
    activeItems.push(mesh);
  });

  // Col 2: COMPANY
  addText("COMPANY", 9, "#7f838a", colX[1], 0.65, 'left');
  const linksCol2 = [
    { text: "Journal", route: "hub-journal" },
    { text: "Visit the Atelier", route: "hub-journal" }, // Fallback route
    { text: "Contact", route: "hub-journal" }
  ];
  linksCol2.forEach((link, idx) => {
    const mesh = addText(link.text, 13, cPaper, colX[1], 0.4 - (idx * 0.2), 'left');
    mesh.userData = { link: link.route, originalColor: cPaper };
    activeItems.push(mesh);
  });

  // Col 3: LEGAL
  addText("LEGAL", 9, "#7f838a", colX[2], 0.65, 'left');
  const linksCol3 = [
    { text: "Privacy", route: "" },
    { text: "Terms", route: "" },
    { text: "Warranty", route: "" }
  ];
  linksCol3.forEach((link, idx) => {
    const mesh = addText(link.text, 13, cPaper, colX[2], 0.4 - (idx * 0.2), 'left');
    mesh.userData = { link: link.route, originalColor: cPaper };
    activeItems.push(mesh);
  });

  // Legal Line (Centered or spanning left at bottom edge bottom margin Y = -0.7)
  addText("(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.", 9, "#7f838a", -3.2, -0.7, 'left');

  // --- INTERACTIONS & RAYCASTING ---
  const raycaster = new Raycaster();
  const mouse = new Vector2();
  let hoveredMesh = null;

  const getIntersection = (event) => {
    const rect = event.renderer.domElement.getBoundingClientRect();
    const x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
    const y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
    mouse.set(x, y);
    raycaster.setFromCamera(mouse, event.camera);
    // Intersection against active text items (children objects inside parent container)
    const targets = [];
    activeItems.forEach(item => {
      item.traverse(child => {
        if (child.isMesh) {
          child.userData.hostParent = item; // Map back to group host
          targets.push(child);
        }
      });
    });
    const intersects = raycaster.intersectObjects(targets);
    return intersects.length > 0 ? intersects[0].object.userData.hostParent : null;
  };

  const onPointerMove = (e) => {
    const hit = getIntersection(e);
    if (hit !== hoveredMesh) {
      if (hoveredMesh) {
        // Hover Out
        const item = hoveredMesh;
        gsap.to(item.position, { z: 0.005, duration: 0.14, ease: "cubic" });
        item.traverse(child => {
          if (child.isMesh && child.material && child.material.color) {
            gsap.to(child.material.color, {
              r: 232/255, g: 236/255, b: 242/255,
              duration: 0.14, ease: "cubic"
            });
          }
        });
      }
      if (hit) {
        // Hover In
        const item = hit;
        gsap.to(item.position, { z: 0.025, duration: 0.14, ease: "cubic" });
        item.traverse(child => {
          if (child.isMesh && child.material && child.material.color) {
            gsap.to(child.material.color, {
              r: 255/255, g: 42/255, b: 56/255,
              duration: 0.14, ease: "cubic"
            });
          }
        });
      }
      hoveredMesh = hit;
    }
  };

  const onPointerDown = (e) => {
    const hit = getIntersection(e);
    if (hit && hit.userData.link) {
      ctx.emit('navigate', { to: hit.userData.link });
    }
  };

  // Register modern handlers
  group.userData.handlers = {
    pointermove: onPointerMove,
    pointerdown: onPointerDown
  };

  // --- TRANSITION MOUNT ---
  // Mount is a single fade-up of the whole band opacity 0 -> 1 and y +0.2 -> 0 over 500ms
  bgMat.opacity = 0;
  group.position.y += 0.2;

  const mountTl = gsap.timeline();
  mountTl.to(bgMat, { opacity: 1, duration: 0.5, ease: "power2.out" }, 0);
  mountTl.to(group.position, { y: 0, duration: 0.5, ease: "power2.out" }, 0);

  // Apply cinematic primitives (none specified but standard contract maintenance)
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      const effect = ctx.primitives[prim.name]?.(group, prim.params);
      if (effect && typeof effect.cleanup === 'function') {
        cleanupTasks.push(effect.cleanup);
      }
    });
  }

  // --- CLEANUP ---
  group.userData.cleanup = () => {
    mountTl.kill();
    cleanupTasks.forEach(task => task());
    bgGeo.dispose();
    bgMat.dispose();
    topHairlineMat.dispose();
    bottomHairlineMat.dispose();
    accentBarMat.dispose();
  };

  return group;
}
